// SPDX-License-Identifier: MIT
pragma solidity 0.8.36;

import { Raffle } from "../src/Raffle.sol";
import { RaffleFactory } from "../src/RaffleFactory.sol";
import { IRaffle } from "../src/interfaces/IRaffle.sol";
import { IRaffleFactory } from "../src/interfaces/IRaffleFactory.sol";
import { ERC721 } from "@openzeppelin/contracts/token/ERC721/ERC721.sol";

interface Vm {
    function warp(uint256) external;
    function prank(address) external;
}

contract MockUSDC {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    uint256 public totalSupply;

    function decimals() external pure returns (uint8) {
        return 6;
    }

    function mint(address to, uint256 a) external {
        balanceOf[to] += a;
        totalSupply += a;
    }

    function approve(address s, uint256 a) external returns (bool) {
        allowance[msg.sender][s] = a;
        return true;
    }

    function transfer(address to, uint256 a) external returns (bool) {
        balanceOf[msg.sender] -= a;
        balanceOf[to] += a;
        return true;
    }

    function transferFrom(address f, address to, uint256 a) external returns (bool) {
        uint256 al = allowance[f][msg.sender];
        if (al != type(uint256).max) allowance[f][msg.sender] = al - a;
        balanceOf[f] -= a;
        balanceOf[to] += a;
        return true;
    }
}

contract MockNFT is ERC721("P", "P") {
    function mint(address to, uint256 id) external {
        _mint(to, id);
    }
}

contract MockWrapper {
    uint256 public lastRequestId;
    uint256 public constant PRICE = 1e15;

    function link() external pure returns (address) {
        return address(0x1111);
    }

    function linkNativeFeed() external pure returns (address) {
        return address(0);
    }

    function calculateRequestPriceNative(uint32, uint32) external pure returns (uint256) {
        return PRICE;
    }

    function estimateRequestPriceNative(uint32, uint32, uint256) external pure returns (uint256) {
        return PRICE;
    }

    function calculateRequestPrice(uint32, uint32) external pure returns (uint256) {
        return PRICE;
    }

    function estimateRequestPrice(uint32, uint32, uint256) external pure returns (uint256) {
        return PRICE;
    }

    function requestRandomWordsInNative(uint32, uint16, uint32, bytes calldata) external payable returns (uint256) {
        require(msg.value >= PRICE, "fee");
        return ++lastRequestId;
    }

    function fulfill(address raffle, uint256 id, uint256 word) external {
        uint256[] memory w = new uint256[](1);
        w[0] = word;
        Raffle(payable(raffle)).rawFulfillRandomWords(id, w);
    }
}

contract LensSixTest {
    Vm internal constant vm = Vm(address(uint160(uint256(keccak256("hevm cheat code")))));

    MockUSDC internal usdc;
    MockNFT internal nft;
    MockWrapper internal wrapper;
    RaffleFactory internal factory;

    address internal constant TREASURY = address(0x7EA5);
    address internal constant SPONSOR = address(0x5905);
    address internal constant SPONSOR_RCPT = address(0x5906);
    uint128 internal constant MAX128 = type(uint128).max;

    function setUp() public {
        usdc = new MockUSDC();
        nft = new MockNFT();
        wrapper = new MockWrapper();
        factory = new RaffleFactory(address(usdc), address(wrapper), TREASURY);
    }

    // helpers

    function _create(uint128 reserve, uint256 prizeId) internal returns (Raffle r) {
        nft.mint(SPONSOR, prizeId);
        vm.prank(SPONSOR);
        nft.setApprovalForAll(address(factory), true);
        vm.prank(SPONSOR);
        address a = factory.createRaffle(
            IRaffleFactory.CreateRaffleParams({
                sponsorRecipient: SPONSOR_RCPT,
                prizeToken: address(nft),
                prizeTokenId: prizeId,
                reserveEntries: reserve,
                endTime: uint64(block.timestamp + 1 days)
            })
        );
        r = Raffle(payable(a));
    }

    function _fund(Raffle r, address buyer, uint256 amount) internal {
        usdc.mint(buyer, amount);
        vm.prank(buyer);
        usdc.approve(address(r), type(uint256).max);
    }

    function _buy(Raffle r, address buyer, uint128 n) internal returns (uint256 id) {
        _fund(r, buyer, uint256(n) * 1e6);
        vm.prank(buyer);
        id = r.buyEntries(buyer, n);
    }

    function _revertSelector(bool ok, bytes memory ret) internal pure returns (bytes4 sel) {
        require(!ok, "expected revert");
        require(ret.length >= 4, "no selector");
        assembly {
            sel := mload(add(ret, 32))
        }
    }

    function _winningTicket(Raffle r) internal view returns (uint256 wt) {
        uint128 we = r.winningEntry();
        uint256 n = r.ticketCount();
        for (uint256 t = 1; t <= n; ++t) {
            (uint128 f, uint128 l) = r.ticketRange(t);
            if (we >= f && we <= l) {
                require(wt == 0, "two tickets contain the winning entry");
                wt = t;
            }
        }
        require(wt != 0, "no ticket contains the winning entry");
    }

    // 1. Split exactness and Last User Out for both resolved branches, fuzzed sizes and randomness.
    function testFuzz_SplitExactAndLastOut(uint64 a, uint64 b, uint64 c, uint256 word, bool meetReserve) public {
        uint128 na = uint128(a % 1_000_000) + 1;
        uint128 nb = uint128(b % 1_000_000) + 1;
        uint128 nc = uint128(c % 1_000_000) + 1;
        uint128 total = na + nb + nc;
        Raffle r = _create(meetReserve ? total : total + 1, 1);
        _buy(r, address(0xB1), na);
        _buy(r, address(0xB2), nb);
        _buy(r, address(0xB3), nc);
        uint256 pot = uint256(total) * 1e6;
        require(r.unsettledPot() == pot && r.grossSales() == pot, "pot");
        require(usdc.balanceOf(address(r)) == r.accountedQuoteBalance(), "solvency pre");

        vm.warp(r.endTime());
        uint256 reqId = r.requestDraw{ value: 1e15 }();
        wrapper.fulfill(address(r), reqId, word);
        uint256 wt = _winningTicket(r);

        uint256 cash = r.settleWinningTicket(wt);
        uint256 fee = r.protocolFees();
        uint256 sp = r.sponsorProceeds();
        require(fee == uint256(total) * 50_000, "fee not exact 5%");
        if (meetReserve) {
            require(r.status() == IRaffle.Status.NftWon, "status nft");
            require(cash == 0 && sp == uint256(total) * 950_000, "nft split");
        } else {
            require(r.status() == IRaffle.Status.CashWon, "status cash");
            require(cash == uint256(total) * 800_000 && sp == uint256(total) * 150_000, "cash split");
        }
        require(fee + cash + sp == pot, "dust");
        require(usdc.balanceOf(address(r)) == r.accountedQuoteBalance(), "solvency post-settle");

        // worst order: winner last
        r.releaseProtocolFees();
        r.releaseSponsorProceeds();
        if (!meetReserve) r.releaseSponsorPrize();
        address winner = r.ownerOf(wt);
        vm.prank(winner);
        r.redeemWinningTicket(wt);
        require(usdc.balanceOf(address(r)) == 0 && r.accountedQuoteBalance() == 0, "last out");
        require(usdc.balanceOf(TREASURY) == fee && usdc.balanceOf(SPONSOR_RCPT) == sp, "payees");
        require(nft.ownerOf(1) == (meetReserve ? winner : SPONSOR_RCPT), "prize");
    }

    // 2. Refund branch Last User Out (both entry routes), fuzzed ticket sizes, batched by holder.
    function testFuzz_RefundLastOut(uint256 seed, uint8 nTickets, bool viaDrawing, uint256 word) public {
        uint256 n = uint256(nTickets) % 30 + 1;
        Raffle r = _create(MAX128, 2);
        uint256 sum;
        for (uint256 i; i < n; ++i) {
            uint128 s = uint128(uint256(keccak256(abi.encode(seed, i))) % 10_000) + 1;
            sum += s;
            _buy(r, address(uint160(0xC000 + (i % 3))), s);
        }

        if (viaDrawing) {
            vm.warp(r.endTime());
            uint256 reqId = r.requestDraw{ value: 1e15 }();
            vm.warp(r.callbackDeadline());
            wrapper.fulfill(address(r), reqId, word); // exactly at the deadline: must be ignored
            require(r.status() == IRaffle.Status.Drawing, "late callback resolved");
        } else {
            vm.warp(r.drawRequestDeadline());
        }
        r.enableRefunds();
        require(r.remainingRefundLiability() == sum * 1e6 && r.unsettledPot() == 0, "liability");

        for (uint256 h = 3; h > 0; --h) {
            address holder = address(uint160(0xC000 + (h - 1)));
            uint256 cnt;
            for (uint256 i = h - 1; i < n; i += 3) {
                ++cnt;
            }
            if (cnt == 0) continue;
            uint256[] memory ids = new uint256[](cnt);
            uint256 k;
            uint256 owed;
            for (uint256 i = h - 1; i < n; i += 3) {
                ids[k++] = i + 1;
                (uint128 f, uint128 l) = r.ticketRange(i + 1);
                owed += (uint256(l) - f + 1) * 1e6;
            }
            uint256 before = usdc.balanceOf(holder);
            vm.prank(holder);
            uint256 paid = r.refundTickets(ids);
            require(paid == owed && usdc.balanceOf(holder) - before == owed, "refund amount");
        }
        require(r.remainingRefundLiability() == 0 && usdc.balanceOf(address(r)) == 0, "refund last out");
        r.releaseSponsorPrize();
        require(nft.ownerOf(2) == SPONSOR_RCPT, "prize back");
    }

    // 3. One-second boundaries: sale/request, request/refund, callback/refund are disjoint and complementary.
    function test_WindowBoundaries() public {
        Raffle r = _create(1, 3);
        _buy(r, address(0xD1), 5);
        vm.warp(r.endTime() - 1);
        _buy(r, address(0xD2), 1); // last second of sale still accepted
        (bool ok, bytes memory ret) = address(r).call{ value: 1e15 }(abi.encodeCall(Raffle.requestDraw, ()));
        require(_revertSelector(ok, ret) == IRaffle.RaffleNotEnded.selector, "early draw");

        vm.warp(r.endTime());
        _fund(r, address(0xD3), 1e6);
        vm.prank(address(0xD3));
        (ok, ret) = address(r).call(abi.encodeCall(Raffle.buyEntries, (address(0xD3), uint128(1))));
        require(_revertSelector(ok, ret) == IRaffle.SaleEnded.selector, "buy at end");

        vm.warp(r.drawRequestDeadline() - 1);
        (ok, ret) = address(r).call(abi.encodeCall(Raffle.enableRefunds, ()));
        require(_revertSelector(ok, ret) == IRaffle.RefundsNotAvailable.selector, "refund before deadline");
        uint256 reqId = r.requestDraw{ value: 1e15 }();

        vm.warp(r.callbackDeadline() - 1);
        (ok, ret) = address(r).call(abi.encodeCall(Raffle.enableRefunds, ()));
        require(_revertSelector(ok, ret) == IRaffle.RefundsNotAvailable.selector, "refund before cb deadline");
        wrapper.fulfill(address(r), reqId, 12_345);
        require(r.status() == IRaffle.Status.NftWon, "cb at deadline-1 resolves");

        Raffle r2 = _create(1, 4);
        _buy(r2, address(0xD4), 2);
        vm.warp(r2.drawRequestDeadline());
        (ok, ret) = address(r2).call{ value: 1e15 }(abi.encodeCall(Raffle.requestDraw, ()));
        require(_revertSelector(ok, ret) == IRaffle.DrawRequestWindowExpired.selector, "draw at deadline");
        r2.enableRefunds();
        require(r2.status() == IRaffle.Status.Refunding, "refunding");
    }

    // 4. A ticket range cannot be refunded twice inside one batch; foreign tickets revert.
    function test_DuplicateAndForeignRefundRevert() public {
        Raffle r = _create(MAX128, 5);
        _buy(r, address(0xE1), 7);
        _buy(r, address(0xE2), 3);
        vm.warp(r.drawRequestDeadline());
        r.enableRefunds();
        uint256[] memory ids = new uint256[](2);
        ids[0] = 1;
        ids[1] = 1;
        vm.prank(address(0xE1));
        (bool ok,) = address(r).call(abi.encodeCall(Raffle.refundTickets, (ids)));
        require(!ok, "duplicate accepted");
        ids[1] = 2;
        vm.prank(address(0xE1));
        (ok,) = address(r).call(abi.encodeCall(Raffle.refundTickets, (ids)));
        require(!ok, "foreign accepted");
        require(r.remainingRefundLiability() == 10e6, "liability moved");
    }

    // 5. uint128 extremes: overflow guard, max winning entry, mulDiv on the largest possible pot.
    function test_Uint128Extremes() public {
        Raffle r = _create(1, 6);
        _buy(r, address(0xF1), 1);
        _fund(r, address(0xF2), uint256(MAX128) * 1e6);
        vm.prank(address(0xF2));
        (bool ok, bytes memory ret) = address(r).call(abi.encodeCall(Raffle.buyEntries, (address(0xF2), MAX128)));
        require(_revertSelector(ok, ret) == IRaffle.TotalEntriesOverflow.selector, "overflow guard");
        vm.prank(address(0xF2));
        uint256 t2 = r.buyEntries(address(0xF2), MAX128 - 1);
        (uint128 f2, uint128 l2) = r.ticketRange(t2);
        require(f2 == 2 && l2 == MAX128 && r.totalEntries() == MAX128, "range at max");
        uint256 pot = uint256(MAX128) * 1e6;
        require(r.unsettledPot() == pot, "pot max");

        vm.warp(r.endTime());
        uint256 reqId = r.requestDraw{ value: 1e15 }();
        wrapper.fulfill(address(r), reqId, uint256(MAX128) - 1); // selects entry MAX128
        require(r.winningEntry() == MAX128, "max entry");
        r.settleWinningTicket(t2);
        require(r.protocolFees() == uint256(MAX128) * 50_000, "fee max");
        require(r.sponsorProceeds() == uint256(MAX128) * 950_000, "sponsor max");
        require(r.protocolFees() + r.sponsorProceeds() == pot, "no dust at max");
        r.releaseProtocolFees();
        r.releaseSponsorProceeds();
        vm.prank(address(0xF2));
        r.redeemWinningTicket(t2);
        require(usdc.balanceOf(address(r)) == 0, "last out at max");
    }

    // 6. Drive to the minimum: one entry, both branches, every leg strictly positive and exact.
    function test_MinimumPot() public {
        Raffle r = _create(2, 7); // 1 entry < reserve 2 -> CashWon
        _buy(r, address(0xA1), 1);
        vm.warp(r.endTime());
        uint256 reqId = r.requestDraw{ value: 1e15 }();
        wrapper.fulfill(address(r), reqId, type(uint256).max);
        require(r.winningEntry() == 1 && r.status() == IRaffle.Status.CashWon, "min cash");
        uint256 cash = r.settleWinningTicket(1);
        require(cash == 800_000 && r.sponsorProceeds() == 150_000 && r.protocolFees() == 50_000, "min split");

        Raffle r2 = _create(1, 8); // 1 entry == reserve 1 -> NftWon
        _buy(r2, address(0xA2), 1);
        vm.warp(r2.endTime());
        reqId = r2.requestDraw{ value: 1e15 }();
        wrapper.fulfill(address(r2), reqId, 0);
        require(r2.status() == IRaffle.Status.NftWon, "min nft");
        require(r2.settleWinningTicket(1) == 0, "nft cash");
        require(r2.sponsorProceeds() == 950_000 && r2.protocolFees() == 50_000, "min nft split");
    }
}

